{
  "items": [
    {
      "name": "Polynomial.coeff_zero_eq_eval_zero",
      "module_name": "Mathlib.Algebra.Polynomial.Eval.Coeff",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R), p.coeff 0 = Polynomial.eval 0 p"
    },
    {
      "name": "rothNumberNat_zero",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Defs",
      "kind": "theorem",
      "type": "rothNumberNat 0 = 0"
    },
    {
      "name": "WittVector.verschiebungPoly_zero",
      "module_name": "Mathlib.RingTheory.WittVector.Verschiebung",
      "kind": "theorem",
      "type": "WittVector.verschiebungPoly 0 = 0"
    },
    {
      "name": "Polynomial.mem_roots_iff_aeval_eq_zero",
      "module_name": "Mathlib.Algebra.Polynomial.Roots",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] [inst_1 : IsDomain R] {p : Polynomial R} {x : R},\n  p ≠ 0 → (x ∈ p.roots ↔ (Polynomial.aeval x) p = 0)"
    },
    {
      "name": "Poly.zero_apply",
      "module_name": "Mathlib.NumberTheory.Dioph",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} (x : α → ℕ), 0 x = 0"
    },
    {
      "name": "Polynomial.eval_zero",
      "module_name": "Mathlib.Algebra.Polynomial.Eval.Defs",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {x : R}, Polynomial.eval x 0 = 0"
    }
  ]
}

{
  "items": [
    {
      "name": "MvPowerSeries.weightedOrder",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "definition",
      "type": "{σ : Type u_1} → {R : Type u_2} → [Semiring R] → (σ → ℕ) → MvPowerSeries σ R → ℕ∞"
    },
    {
      "name": "MvPowerSeries.weightedOrder_eq_nat",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {n : ℕ},\n  MvPowerSeries.weightedOrder w f = ↑n ↔\n    (∃ d, (MvPowerSeries.coeff d) f ≠ 0 ∧ (Finsupp.weight w) d = n) ∧\n      ∀ (d : σ →₀ ℕ), (Finsupp.weight w) d < n → (MvPowerSeries.coeff d) f = 0"
    },
    {
      "name": "MvPowerSeries.ne_zero_iff_exists_coeff_ne_zero_and_weight",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R},\n  f ≠ 0 ↔ ∃ n d, (MvPowerSeries.coeff d) f ≠ 0 ∧ (Finsupp.weight w) d = n"
    },
    {
      "name": "analyticOrderAt",
      "module_name": "Mathlib.Analysis.Analytic.Order",
      "kind": "definition",
      "type": "{𝕜 : Type u_1} →\n  {E : Type u_2} →\n    [inst : NontriviallyNormedField 𝕜] → [inst_1 : NormedAddCommGroup E] → [NormedSpace 𝕜 E] → (𝕜 → E) → 𝕜 → ℕ∞"
    },
    {
      "name": "MvPowerSeries.coeff_eq_zero_of_lt_weightedOrder",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {d : σ →₀ ℕ},\n  ↑((Finsupp.weight w) d) < MvPowerSeries.weightedOrder w f → (MvPowerSeries.coeff d) f = 0"
    },
    {
      "name": "MvPowerSeries.weightedOrder_monomial",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {d : σ →₀ ℕ} {a : R} [inst_1 : Decidable (a = 0)],\n  MvPowerSeries.weightedOrder w ((MvPowerSeries.monomial d) a) = if a = 0 then ⊤ else ↑((Finsupp.weight w) d)"
    }
  ]
}

{
  "items": [
    {
      "name": "Finset.inf_eq_bot_iff",
      "module_name": "Mathlib.Data.Finset.Lattice.Fold",
      "kind": "theorem",
      "type": "∀ {ι : Type u_5} {α : Type u_7} [inst : LinearOrder α] [inst_1 : BoundedOrder α] [Nontrivial α] {s : Finset ι}\n  {f : ι → α}, s.inf f = ⊥ ↔ ∃ b ∈ s, f b = ⊥"
    },
    {
      "name": "csInf_eq_bot_of_bot_mem",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : ConditionallyCompleteLinearOrder α] [inst_1 : OrderBot α] {s : Set α}, ⊥ ∈ s → sInf s = ⊥"
    },
    {
      "name": "inf_eq_bot_of_bot_mem",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : ConditionallyCompleteLattice α] {s : Set α} [inst_1 : OrderBot α], ⊥ ∈ s → sInf s = ⊥"
    },
    {
      "name": "inf_bot_eq",
      "module_name": "Mathlib.Order.BoundedOrder.Lattice",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : SemilatticeInf α] [inst_1 : OrderBot α] (a : α), a ⊓ ⊥ = ⊥"
    },
    {
      "name": "sInf_eq_bot",
      "module_name": "Mathlib.Order.CompleteLattice.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : CompleteLinearOrder α] {s : Set α}, sInf s = ⊥ ↔ ∀ b > ⊥, ∃ a ∈ s, a < b"
    },
    {
      "name": "Finset.Nonempty.inf_eq_bot_iff",
      "module_name": "Mathlib.Data.Finset.Lattice.Fold",
      "kind": "theorem",
      "type": "∀ {ι : Type u_5} {α : Type u_7} [inst : LinearOrder α] [inst_1 : BoundedOrder α] {s : Finset ι} {f : ι → α},\n  s.Nonempty → (s.inf f = ⊥ ↔ ∃ b ∈ s, f b = ⊥)"
    }
  ]
}

